CREATE OR REPLACE FUNCTION trip_private.post_game_night_poll(p_trip uuid,p_options jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can post times'; END IF; IF jsonb_typeof(p_options)<>'array' OR jsonb_array_length(p_options) NOT BETWEEN 3 AND 5 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_options) AS o(v) WHERE (v::timestamptz <= now() OR v::timestamptz >= (SELECT start_date FROM public.trips WHERE id=p_trip) OR length(v)>40)) THEN RAISE EXCEPTION 'Add 3 to 5 future times before the trip'; END IF; DELETE FROM public.game_nights WHERE trip_id=p_trip; DELETE FROM public.game_night_polls WHERE trip_id=p_trip; DELETE FROM public.trip_play_state WHERE trip_id=p_trip; INSERT INTO public.game_night_polls(trip_id,options) VALUES(p_trip,p_options); END $fn$;
CREATE OR REPLACE FUNCTION trip_private.spin_next_game(p_trip uuid) RETURNS TABLE(game_number integer,week_number integer,spin_time timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_week integer; v_game integer; v_used integer[]; v_now timestamptz := clock_timestamp(); BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF; SELECT n.week_number INTO v_week FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at<=v_now ORDER BY n.starts_at DESC LIMIT 1; IF v_week IS NULL THEN RAISE EXCEPTION 'Wait for the first game night'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND (m.role IN ('captain','co_captain') OR m.user_id=(SELECT n.host_id FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week))) THEN RAISE EXCEPTION 'Only a leader or this week''s host can spin'; END IF; INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING; SELECT used_games INTO v_used FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=v_week+1 AND game_number IS NULL) THEN RAISE EXCEPTION 'No unassigned next week'; END IF; IF cardinality(v_used)>=12 THEN v_used:='{}'; END IF; SELECT number INTO v_game FROM public.game_catalog WHERE NOT(number=ANY(v_used)) ORDER BY random() LIMIT 1; UPDATE public.game_nights SET game_number=v_game WHERE trip_id=p_trip AND week_number=v_week+1 AND game_number IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'No unassigned next week'; END IF; UPDATE public.trip_play_state SET used_games=array_append(v_used,v_game),spin_game=v_game,spin_week=v_week+1,spin_at=v_now WHERE trip_id=p_trip; RETURN QUERY SELECT v_game,v_week+1,v_now; END $fn$;